css_extra:
/* ===== Aula 06 — componentes ===== */
.ic { width:22px; height:22px; flex-shrink:0 }
.lead { font-size:18px; line-height:1.5; color:var(--c); margin:0 }
.lead strong { color:var(--p) }
.slbd.g > .grade:first-child:has(.lead) { align-self:start }
.lead-card { justify-content:center; gap:14px; padding:20px 24px }
.lead-card .lead + .lead { margin-top:12px }
.slbd.g a { color:var(--bem); font-weight:600 }
.mini { font-size:15px !important; color:var(--tx-apoio); line-height:1.4 }
/* cartões com ícone e cor de acento */
.card.cx { --k:var(--ve); border-top:4px solid var(--k); flex:1 1 0; gap:8px; justify-content:center; padding:16px 20px }
.cx-bd p { font-size:17.5px !important; line-height:1.5 }
.card.cx.k2 { --k:#0EA5E9 } .card.cx.k3 { --k:#F59E0B } .card.cx.k4 { --k:#8B5CF6 }
.cx-hd { display:flex; align-items:center; gap:10px }
.cx-hd h3 { margin:0 !important; color:var(--p) !important; font-size:18px }
.cic { width:38px; height:38px; border-radius:10px; display:grid; place-items:center; color:var(--k);
  background:color-mix(in srgb, var(--k) 13%, #fff); flex-shrink:0 }
.cx-bd p { margin:0 } .cx-bd p + p { margin-top:8px }
/* linha do tempo */
.tl { list-style:none; margin:0; display:flex; flex-direction:column; justify-content:space-between; height:100%; position:relative; padding-left:6px }
.tl::before { content:""; position:absolute; left:15px; top:12px; bottom:12px; width:3px; background:linear-gradient(var(--ve),var(--fita2)) }
.tl li { position:relative; padding:4px 0 4px 40px !important; margin:0 !important }
.tl li::before { content:"" !important; position:absolute; left:2px !important; top:7px !important; width:20px !important; height:20px !important;
  border-radius:50%; background:#fff !important; border:4px solid var(--ve); margin:0 !important }
.tl li.hoje::before { background:var(--ve) !important }
.tl b { display:block; color:var(--bem); font-size:17px }
.tl span { display:block; font-size:16px; line-height:1.4; color:var(--c) }
/* figuras sem moldura */
.fig.fig-limpa { border:0; background:transparent; padding:0 }
.fig svg.browser { width:100%; height:100%; max-height:100% }
/* atividade */
.ativ { justify-content:center; gap:10px; padding:22px 26px }
.ativ-tit { font-size:24px !important; line-height:1.25; color:var(--p) !important; margin:0 !important }
.ativ p { margin:0 }
.ativ .dica { font-size:15px; color:var(--vd-tx); font-style:italic }
.tag-tempo { align-self:flex-start; display:inline-flex; gap:6px; align-items:center; background:var(--ve); color:#fff; font-weight:700;
  font-size:14px; padding:5px 12px; border-radius:20px }
.tag-tempo .ic { width:18px; height:18px }
/* níveis de ISP */
.niveis { display:flex; flex-direction:column; gap:10px; justify-content:center; height:100% }
.nv { border-radius:12px; padding:10px 14px; border-left:6px solid; background:var(--card-bg) }
.nv b { display:block; font-size:17px } .nv span { font-size:15.5px; line-height:1.4; color:var(--c) }
.nv.l { border-color:#A7F3D0 } .nv.m { border-color:#115E59 } .nv.a { border-color:#0B231C } .nv.p { border-color:#F59E0B; background:#FFF7E6 }
/* links externos */
.lk { display:flex; align-items:center; gap:12px; text-decoration:none; color:var(--p) !important; background:#fff; border:1px solid var(--linha);
  border-radius:12px; padding:10px 14px; transition:border-color .15s, box-shadow .15s; flex:0 0 auto }
.lk:hover { border-color:var(--ve); box-shadow:0 4px 14px rgba(14,159,110,.15) }
.lk > .ic:first-child { width:30px; height:30px; color:var(--ve) }
.lk span { display:flex; flex-direction:column; min-width:0; flex:1 }
.lk b { font-size:16px } .lk small { font-size:14px; color:var(--c); font-weight:400; line-height:1.35 }
.lk em { font-size:13px; color:var(--bem); font-style:normal; font-weight:600 }
.lk .lk-ext { width:18px; height:18px; color:var(--c) }
.lks2 { display:grid; grid-template-columns:1fr 1fr; gap:14px }
.destaque-local { display:flex; gap:12px; align-items:flex-start; margin-top:14px; background:#FFF7E6; border:1px solid #FCD9A0; border-radius:12px; padding:12px 14px }
.destaque-local .ic { color:#B45309; width:26px; height:26px; margin-top:2px }
.destaque-local span { font-size:16.5px; line-height:1.45 }
/* incorporados */
.emb { position:relative; flex:1; min-height:0; border-radius:14px; overflow:hidden; border:1px solid var(--linha); background:#fff; display:flex }
.emb iframe { position:relative; flex:1; width:100%; height:100%; border:0; background:transparent }
.emb::before { content:"Carregando conteúdo interativo… (requer internet)"; position:absolute; inset:0; display:grid; place-items:center; color:var(--tx-apoio); font-size:16px }
.video-emb::before { color:#94A3B8 }
.passos { margin:auto 0 }
.video-emb { background:#000 }
.kpi-col { display:flex; flex-direction:column; gap:10px; flex:1 }
.kpi-col > div { flex:1; padding:10px 16px }
.kpi-col b { font-size:28px }
/* URL */
.url { display:flex; flex-wrap:wrap; justify-content:center; flex-wrap:nowrap; white-space:nowrap; font:700 31px/1 ui-monospace, 'SF Mono', Menlo, Consolas, monospace; margin:auto 0 8px; position:relative; padding-bottom:96px; padding-top:20px }
.u { position:static; padding:8px 3px 10px; border-bottom:5px solid var(--uc); cursor:help; color:var(--uc); outline:none }
.u i { display:none; position:absolute; left:0; right:0; bottom:0; font:500 16px/1.4 var(--fonte); color:var(--p);
  background:color-mix(in srgb, var(--uc) 10%, #fff); border-left:5px solid var(--uc); border-radius:8px; padding:10px 14px; font-style:normal }
.u:hover i, .u:focus i { display:block }
.url:not(:hover):not(:focus-within) .u3 i { display:block }
.u1 { --uc:#0E9F6E } .u2 { --uc:#0EA5E9 } .u3 { --uc:#8B5CF6 } .u4 { --uc:#F59E0B } .u5 { --uc:#DC2626 }
.url-dica { font-size:14px !important; color:var(--tx-apoio); margin:0 0 auto; text-align:center }
.u i { font-size:18px !important }
.tb2.dom td { padding:7px 10px !important; text-align:left !important }
.tb2.dom code { font-weight:700; color:var(--bem); font-size:16px }
/* navegadores */
.card.nav { align-items:center; text-align:center; justify-content:center; gap:8px; padding:18px 16px; height:100% }
.nav-ic { width:66px; height:66px; border-radius:50%; display:grid; place-items:center; font-size:30px; font-weight:800; color:#fff;
  background:radial-gradient(circle at 30% 30%, color-mix(in srgb, var(--c) 60%, #fff), var(--c)); box-shadow:0 6px 16px color-mix(in srgb, var(--c) 35%, transparent) }
.card.nav h3 { margin:4px 0 0 !important; color:var(--p) }
.card.nav p { margin:0; font-size:17px !important; line-height:1.5 }
.nav-ic { width:84px !important; height:84px !important; font-size:38px !important; margin-bottom:8px }
/* elementos do navegador */
.elem { list-style:none; margin:0; display:flex; flex-direction:column; gap:8px; counter-reset:el; height:100%; justify-content:center }
.elem li { counter-increment:el; display:flex; gap:12px; align-items:flex-start; padding:0 !important; margin:0 !important }
.elem li::before { content:counter(el) !important; position:static !important; flex-shrink:0; width:30px !important; height:30px !important; border-radius:50%;
  background:#F59E0B !important; color:#fff; font-weight:800; display:grid; place-items:center; font-size:15px; margin:0 !important }
.elem li > div > b { display:block; font-size:17px } .elem li > div > span { display:block; font-size:15.5px; line-height:1.4; color:var(--c) }
/* operadores de busca */
.ops { display:grid; grid-template-columns:1fr 1fr; gap:10px; height:100%; align-content:center }
.op { display:grid; grid-template-columns:150px 1fr; grid-template-rows:auto auto; column-gap:12px; align-items:center; text-decoration:none;
  background:var(--card-bg); border:1px solid var(--linha); border-radius:12px; padding:9px 14px; color:var(--p) !important; font-weight:400 !important }
.op:hover { border-color:var(--ve); background:#fff }
.op-n { grid-row:1 / 3; font-weight:800; color:var(--bem); font-size:16px }
.op code { font-size:15.5px; font-weight:600; color:var(--p); background:#fff; border:1px solid var(--linha); border-radius:6px; padding:2px 8px; justify-self:start }
.op small { font-size:14.5px; color:var(--c); margin-top:3px }
.op:hover code::after { content:" ↗"; color:var(--ve) }
/* aviso */
.aviso { display:flex; gap:12px; align-items:center; background:var(--aviso-bg); border:1px solid #FCD9A0; border-radius:12px; padding:10px 16px; color:var(--aviso-tx) }
.aviso .ic { width:26px; height:26px; color:#D97706 }
.aviso span { font-size:15.5px; line-height:1.45 }
/* download / upload */
.dupla { display:flex; flex-direction:column; gap:10px; flex:1; justify-content:center }
.dupla > div { display:grid; grid-template-columns:40px 1fr; column-gap:10px; background:var(--card-bg); border:1px solid var(--linha); border-radius:12px; padding:10px 14px }
.dupla .ic { grid-row:1 / 3; width:32px; height:32px; color:var(--ve); align-self:center }
.dupla b { font-size:17px } .dupla span { font-size:15.5px; line-height:1.4; color:var(--c) }
ul.chk li { margin:6px 0 }
/* e-mail */
.mail { display:flex; font:700 30px/1 ui-monospace, Menlo, Consolas, monospace; margin:10px 0 14px; flex-wrap:wrap }
.mail span { padding:6px 2px 8px; border-bottom:5px solid }
.mail .m1 { color:#0E9F6E } .mail .m2 { color:#64748B } .mail .m3 { color:#8B5CF6 } .mail .m4 { color:#F59E0B }
.rev { text-align:left; margin:6px 0; display:block }
.rev > span { font-size:18px }
.rev:not(.rv) > span::after { content:"  · clique"; font-weight:400; color:var(--tx-apoio); font-size:14px }
/* passos do Gmail */
.passo { flex:1; display:grid; grid-template-columns:auto auto 1fr; gap:14px; align-items:center; background:var(--card-bg); border:1px solid var(--linha); border-radius:14px; padding:12px 18px }
.passo .pn { font-size:26px; font-weight:800; color:var(--destaque); -webkit-text-stroke:1px var(--bem) }
.passo > .ic { width:32px; height:32px; color:var(--ve) }
.passo div > b { display:block; font-size:18px } .passo div > span { display:block; font-size:16px; line-height:1.45; color:var(--c) }
/* softwares ambientais */
.soft { flex:1 1 0; display:flex; flex-direction:column; gap:6px; text-decoration:none; color:var(--p) !important; font-weight:400 !important;
  background:var(--card-bg); border:1px solid var(--linha); border-top:4px solid var(--ve); border-radius:14px; padding:12px 16px; transition:box-shadow .15s }
.soft:hover { box-shadow:0 6px 18px rgba(14,159,110,.18) }
.soft-hd { display:flex; align-items:center; gap:8px; flex-wrap:wrap }
.soft-hd .ic { width:26px; height:26px; color:var(--ve) }
.soft-hd b { font-size:17.5px }
.soft .tag { margin-left:auto; font-size:12px; font-weight:700; background:var(--azc); color:var(--bem2); border-radius:20px; padding:2px 9px }
.soft p { margin:0; font-size:15px !important; line-height:1.4 }
.soft em { margin-top:auto; font-size:13px; color:var(--bem); font-style:normal; font-weight:600 }
.col > .soft { flex:1 1 0 }
/* capa */
.capa .esq .lk { margin-top:18px; background:rgba(255,255,255,.08); border-color:rgba(255,255,255,.25); color:#fff !important; max-width:520px }
.capa .esq .lk b { color:#fff } .capa .esq .lk small { color:#D1FAE5 } .capa .esq .lk em { color:var(--destaque) }
.capa .esq .lk > .ic:first-child { color:var(--destaque) } .capa .esq .lk .lk-ext { color:#fff }
.capa .esq .sub.aula { font-size:22px; font-weight:800; color:var(--destaque); opacity:1 }
.capa .dir img.ilu { max-width:82%; max-height:80% }
.capa.fim .esq .sub { font-size:19px; max-width:620px }
/* divisórias com fundo gerado */
.divisor .in h1 { font-size:46px }
.divisor .in p { font-size:20px; opacity:.9 }
.divisor .in .rot { font-size:14px }
/* prática de e-mail */
.bp-mail { gap:6px; justify-content:space-evenly }
.bp-mail li > div > span { font-size:15px }
.mailbox { flex:1 1 auto; display:flex; flex-direction:column; background:#fff; border:1px solid var(--linha); border-radius:14px; overflow:hidden; box-shadow:0 6px 18px rgba(0,0,0,.06) }
.mb-hd { display:flex; align-items:center; gap:8px; background:var(--az); color:#fff; padding:9px 16px; font-size:15px }
.mb-hd .ic { color:var(--destaque) }
.mb-l { display:flex; gap:12px; align-items:baseline; padding:7px 16px; border-bottom:1px solid var(--linha); font-size:15.5px }
.mb-l > span { width:62px; flex-shrink:0; color:var(--tx-apoio); font-size:14px }
.mb-l code { font-size:15px; font-weight:700; color:var(--bem) }
.mb-l em { color:var(--tx-apoio) }
.mb-bd { padding:10px 16px; flex:1 }
.mb-bd p { margin:0 0 8px; font-size:15.5px !important; line-height:1.45 }
.mb-ft { display:flex; gap:8px; align-items:center; padding:7px 16px; background:var(--card-bg); border-top:1px solid var(--linha); font-size:14px; color:var(--c) }
.mb-ft .ic { width:18px; height:18px; color:var(--ve) }
@media print { .emb iframe { display:none } .emb::before { content:"Conteúdo interativo: abra a versão web da apresentação" } }
